 * don't name a live issue of this org are skipped rather than failing. Every
 * remaining issue must pass the same `issue:archive` check as a solo archive
 * (ownership escalation included) before anything is written — one failure
 * rejects the whole batch and publishes nothing.
 */
export async function bulkArchiveIssues(
  actor: Actor,
  input: BulkArchiveIssuesInput,
